/* ══════════════════════════════════════════════════════════════
   nj-common.js — 누제믹 페이지 통합 공용 스크립트

   index.html(언어선택) · home.html · moru/ring/earring/earcuff.html
   맨 아래 </body> 직전에 이 한 줄만 넣으면 됩니다.
     <script src="nj-common.js"></script>

   하는 일
   - store/lang 을 주소(?store=, ?lang=)와 localStorage 로 유지
   - 홈 화면의 data-cat 버튼 → 각 상품 페이지로 이동 (phone은 공식 사이트 폰케이스 파트로)
   - 언어 선택 화면의 data-lang 버튼 → 언어 저장 + GA4 이벤트 + 홈으로 이동
   - 상품 페이지 하단의 data-link 버튼(instagram/website/site-ring/home/map) 연결
   - "매장 오시는 길" 팝업 (챗봇의 매장 정보 카드와 동일한 구성: 매장 2곳 × 지도 링크 2개)
   - 챗봇 FAB(njOpenChatbot)·커스텀 버튼(njOpenSimulation) → nj-widget.js 연결
   - GA4 로더 (측정 ID는 자리표시자이며, GA4 속성을 만든 뒤 GA_ID 값만 바꾸면 됩니다)
   ══════════════════════════════════════════════════════════════ */
(function(){
  'use strict';

  /* ── GA4: 속성을 만들면 이 값만 실제 측정 ID로 바꾸세요 ── */
  var GA_ID = 'G-XXXXXXXXXX';

  /* 상품 페이지 FAB과 똑같은 사진 아이콘 (widget 자체 버튼이 뜨는 화면, 예: 홈)에서도
     같은 아이콘을 쓰기 위한 데이터. 절대 다른 아이콘으로 안 보이게 고정합니다. */
  var FAB_ICON = 'data:image/png;base64,';
  (function loadGA(){
    if (window.__njGA) return;
    window.__njGA = true;
    window.dataLayer = window.dataLayer || [];
    window.gtag = function(){ window.dataLayer.push(arguments); };
    window.gtag('js', new Date());
    window.gtag('config', GA_ID);
    var s = document.createElement('script');
    s.async = true;
    s.src = 'https://www.googletagmanager.com/gtag/js?id=' + GA_ID;
    document.head.appendChild(s);
  })();

  /* ── store / lang 상태: 주소 → localStorage → 기본값 순으로 결정 ──
     프라이빗 브라우징이나 일부 인앱 브라우저(카카오톡 등)에서는 localStorage
     접근 자체가 예외를 던질 수 있어서, 안 감싸면 이 스크립트 전체가 그 자리에서
     멈춰버립니다(라우팅·챗봇 전부 먹통). 그래서 읽기/쓰기 전부 try/catch로 감쌉니다. */
  function safeGet(k){ try{ return localStorage.getItem(k); }catch(_){ return null; } }
  function safeSet(k,v){ try{ localStorage.setItem(k,v); }catch(_){} }

  var Q = new URLSearchParams(location.search);
  var qStore = Q.get('store');
  var STORE = (qStore === 'main' || qStore === 'yeonbang')
            ? qStore
            : (safeGet('nj_store') || 'main');
  var LANG = Q.get('lang') || safeGet('nj_lang') || 'ko';
  safeSet('nj_store', STORE);
  safeSet('nj_lang', LANG);

  function withParams(url){
    var hashIdx = url.indexOf('#');
    var hash = hashIdx >= 0 ? url.slice(hashIdx) : '';
    var base = hashIdx >= 0 ? url.slice(0, hashIdx) : url;
    var path = base.split('?')[0];
    return path + '?store=' + encodeURIComponent(STORE) + '&lang=' + encodeURIComponent(LANG) + hash;
  }
  window.njGoto = function(url){ location.href = withParams(url); };

  /* ── 언어 선택 화면(index.html): data-lang 버튼 ── */
  var langBtns = document.querySelectorAll('[data-lang]');
  var isLanguagePage = langBtns.length > 0;
  langBtns.forEach(function(btn){
    btn.addEventListener('click', function(){
      var l = btn.getAttribute('data-lang');
      LANG = l;
      safeSet('nj_lang', l);
      if (window.gtag) window.gtag('event', 'select_language', { language: l });
      window.njGoto('home.html');
    });
  });

  /* ── 홈 화면(home.html): data-cat 버튼 ── */
  var PAGE_ROUTES = { moru:'moru.html', ring:'ring.html', earring:'earring.html', cuff:'earcuff.html' };
  var PHONE_URL = 'https://www.nujeahmik.com/online-shop';
  var catBtns = document.querySelectorAll('[data-cat]');
  var isHomePage = catBtns.length > 0;
  catBtns.forEach(function(btn){
    var cat = btn.getAttribute('data-cat');
    if (cat === 'phone'){
      btn.addEventListener('click', function(){
        if (window.gtag) window.gtag('event', 'select_category', { category:'phone', to:'official_site' });
        window.open(PHONE_URL, '_blank', 'noopener');
      });
      return;
    }
    var to = PAGE_ROUTES[cat];
    if (!to) return; /* 대응 페이지가 없는 카테고리는 그대로 반응 없음 */
    btn.addEventListener('click', function(){
      if (window.gtag) window.gtag('event', 'select_category', { category: cat });
      window.njGoto(to);
    });
  });

  /* ── 상품 페이지 하단 공통 data-link 버튼 ── */
  var EXTERNAL_LINKS = {
    instagram:  'https://instagram.com/nuj_eahmik',
    website:    'https://www.nujeahmik.com/',
    'site-ring':'https://www.nujeahmik.com/online-shop',
    smartstore: 'https://smartstore.naver.com/nujeahmik'
  };
  document.querySelectorAll('[data-link]').forEach(function(a){
    var kind = a.getAttribute('data-link');
    if (kind === 'home'){
      a.addEventListener('click', function(e){ e.preventDefault(); window.njGoto('home.html'); });
      return;
    }
    if (kind === 'map'){
      a.addEventListener('click', function(e){ e.preventDefault(); openStoreSheet(); });
      return;
    }
    if (EXTERNAL_LINKS[kind]){
      a.setAttribute('href', EXTERNAL_LINKS[kind]);
      a.setAttribute('target', '_blank');
      a.setAttribute('rel', 'noopener');
    }
    /* data-link="simulation" 은 각 페이지 자체 njOpenSimulation()이 처리합니다 */
  });

  /* ── 챗봇 FAB / 커스텀 버튼 → nj-widget.js 로 직접 연결 (인수인계 문서 옵션 A) ── */
  window.njOpenChatbot = function(){ if (window.njChat) window.njChat.open(); };
  window.njOpenSimulation = function(){ window.njGoto('custom.html'); };

  /* 언어 선택 화면 전에는 챗봇이 필요 없으므로 위젯을 불러오지 않습니다.
     상품 상세 페이지는 이미 자체 챗봇 버튼(.fab)이 있으므로 위젯 자체 버튼은 숨깁니다(button:'0'). */
  var hasOwnFab = document.querySelector('.fab') !== null;
  if (!isLanguagePage && !window.__njWidgetLoaded){
    window.__njWidgetLoaded = true;
    window.NJ_WIDGET = { store: STORE, lang: LANG, mode: 'panel', button: hasOwnFab ? '0' : '1', icon: FAB_ICON };
    var ws = document.createElement('script');
    ws.src = 'nj-widget.js';
    ws.setAttribute('data-chat', 'chat.html');
    ws.setAttribute('data-custom', 'custom.html');
    document.body.appendChild(ws);
  }

  /* ── 오른쪽 위 언어 전환 버튼 — 처음 언어를 고른 뒤에도 챗봇을 안 열어도
     언제든 다시 언어를 바꿀 수 있게 합니다. 언어 선택 화면(index.html) 자체에는
     이미 버튼이 있으니 중복으로 넣지 않습니다. */
  var LANG_LABELS = { ko:'한국어', en:'English', cn:'中文 简体', tw:'中文 繁體', jp:'日本語' };
  var LANG_SHORT  = { ko:'한', en:'EN', cn:'简', tw:'繁', jp:'日' };
  var LANG_COLORS = { ko:'#F291AE', en:'#7ED4C0', cn:'#FBD46D', tw:'#B296EE', jp:'#8CB4F0' };

  if (!isLanguagePage) buildLangSwitcher();

  function buildLangSwitcher(){
    injectLangCSS();
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'nj-lang-btn';
    btn.setAttribute('aria-label', '언어 선택');
    /* 배너·다른 버튼과 안 겹치도록 아주 작은 원형 배지 하나로만 (글자 하나~두 글자) */
    btn.textContent = LANG_SHORT[LANG] || '한';
    document.body.appendChild(btn);

    var wrap = document.createElement('div');
    wrap.className = 'nj-langsheet';
    wrap.innerHTML =
      '<div class="nj-ls-dim"></div>' +
      '<div class="nj-ls-card" role="dialog" aria-label="언어 선택">' +
        '<div class="nj-ls-grab"></div>' +
        '<h4>언어를 선택해 주세요</h4>' +
        '<div class="nj-ls-grid">' +
          Object.keys(LANG_LABELS).map(function(code){
            var wide = code === 'jp' ? ' nj-ls-wide' : '';
            return '<button type="button" class="nj-ls-btn' + wide + '" data-l="' + code + '" style="background:' + LANG_COLORS[code] + '">' + LANG_LABELS[code] + '</button>';
          }).join('') +
        '</div>' +
      '</div>';
    document.body.appendChild(wrap);

    function openLs(){ wrap.classList.add('on'); }
    function closeLs(){ wrap.classList.remove('on'); }
    btn.addEventListener('click', openLs);
    wrap.querySelector('.nj-ls-dim').addEventListener('click', closeLs);
    wrap.querySelectorAll('.nj-ls-btn').forEach(function(b){
      b.addEventListener('click', function(){
        var l = b.getAttribute('data-l');
        LANG = l;
        safeSet('nj_lang', l);
        if (window.gtag) window.gtag('event', 'select_language', { language: l, source: 'switcher' });
        var file = location.pathname.split('/').pop() || 'home.html';
        window.njGoto(file);
      });
    });
  }

  function injectLangCSS(){
    if (document.getElementById('nj-lang-style')) return;
    var st = document.createElement('style');
    st.id = 'nj-lang-style';
    st.textContent =
      '.nj-lang-btn{position:fixed;top:calc(10px + env(safe-area-inset-top));right:10px;z-index:2147483500;' +
        'width:34px;height:34px;display:flex;align-items:center;justify-content:center;' +
        'background:#fff;color:#282532;border:none;border-radius:50%;padding:0;' +
        'font-family:"Noto Sans KR",-apple-system,BlinkMacSystemFont,system-ui,sans-serif;' +
        'font-weight:700;font-size:12px;box-shadow:0 3px 10px rgba(31,31,46,.2);cursor:pointer}' +
      '.nj-lang-btn:active{transform:scale(.95)}' +
      '.nj-langsheet{position:fixed;inset:0;z-index:2147483550;display:flex;align-items:flex-end;justify-content:center;pointer-events:none}' +
      '.nj-langsheet.on{pointer-events:auto}' +
      '.nj-ls-dim{position:absolute;inset:0;background:rgba(20,20,24,.4);opacity:0;transition:opacity .25s}' +
      '.nj-langsheet.on .nj-ls-dim{opacity:1}' +
      '.nj-ls-card{position:relative;width:100%;max-width:430px;background:#fff;border-radius:24px 24px 0 0;' +
        'padding:10px 22px calc(24px + env(safe-area-inset-bottom));box-shadow:0 -10px 30px rgba(20,20,40,.18);' +
        'transform:translateY(100%);transition:transform .32s cubic-bezier(.2,.9,.3,1.05);' +
        'font-family:"Noto Sans KR",-apple-system,BlinkMacSystemFont,system-ui,sans-serif;box-sizing:border-box}' +
      '.nj-langsheet.on .nj-ls-card{transform:translateY(0)}' +
      '.nj-ls-grab{width:36px;height:4px;border-radius:2px;background:#e2dfe8;margin:8px auto 14px}' +
      '.nj-ls-card h4{font-size:15px;font-weight:700;color:#282532;margin:0 0 14px;text-align:center}' +
      '.nj-ls-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}' +
      '.nj-ls-btn{height:54px;border:none;border-radius:999px;color:#fff;font-weight:700;' +
        'font-size:14.5px;cursor:pointer;box-shadow:0 3px 9px rgba(31,23,51,.16)}' +
      '.nj-ls-btn:active{transform:scale(.96)}' +
      '.nj-ls-wide{grid-column:1/-1}';
    document.head.appendChild(st);
  }

  /* ── 매장 오시는 길 팝업: 챗봇의 "매장 정보" 카드와 같은 구성
     (매장 2곳 × 구글/네이버 지도 링크 2개 = 총 4개 링크) ── */
  var STORES = {
    main:     { name:'성수본점',   addr:'서울 성동구 연무장길 110, 1층 101호',
                map:'https://maps.app.goo.gl/aUJT6yrhkuuDx8Aq6', naver:'https://naver.me/x1VsvhOF',
                color:'#F5679B', tax:true },
    yeonbang: { name:'성수연방점', addr:'서울 성동구 성수이로14길 14, 1층',
                map:'https://maps.app.goo.gl/qCDCTuBfzVYQkSQ79', naver:'https://naver.me/GM3ZLRGA',
                color:'#3FC7B4', tax:false }
  };

  var sheetEl = null;
  function openStoreSheet(){
    if (!sheetEl) buildSheet();
    requestAnimationFrame(function(){ sheetEl.classList.add('on'); });
    if (window.gtag) window.gtag('event', 'view_store_map');
  }
  function closeSheet(){ if (sheetEl) sheetEl.classList.remove('on'); }

  function buildSheet(){
    injectSheetCSS();
    var wrap = document.createElement('div');
    wrap.className = 'nj-mapsheet';
    wrap.innerHTML =
      '<div class="nj-ms-dim"></div>' +
      '<div class="nj-ms-card" role="dialog" aria-label="매장 오시는 길">' +
        '<div class="nj-ms-grab"></div>' +
        '<h4>매장 오시는 길</h4>' +
        Object.keys(STORES).map(function(k){
          var s = STORES[k];
          return '<div class="nj-ms-store">' +
            '<div class="nj-ms-t"><i style="background:' + s.color + '"></i>' + s.name +
              (s.tax ? '<span class="nj-ms-badge">TAX FREE</span>' : '') + '</div>' +
            '<div class="nj-ms-a">' + s.addr + '</div>' +
            '<div class="nj-ms-links">' +
              '<a href="' + s.map + '" target="_blank" rel="noopener">구글 지도 열기 →</a>' +
              '<a href="' + s.naver + '" target="_blank" rel="noopener">네이버 지도 열기 →</a>' +
            '</div></div>';
        }).join('') +
        '<button type="button" class="nj-ms-close">닫기</button>' +
      '</div>';
    document.body.appendChild(wrap);
    wrap.querySelector('.nj-ms-dim').addEventListener('click', closeSheet);
    wrap.querySelector('.nj-ms-close').addEventListener('click', closeSheet);
    sheetEl = wrap;
  }

  function injectSheetCSS(){
    if (document.getElementById('nj-ms-style')) return;
    var st = document.createElement('style');
    st.id = 'nj-ms-style';
    st.textContent =
      '.nj-mapsheet{position:fixed;inset:0;z-index:2147483600;display:flex;align-items:flex-end;justify-content:center;pointer-events:none}' +
      '.nj-mapsheet.on{pointer-events:auto}' +
      '.nj-ms-dim{position:absolute;inset:0;background:rgba(20,20,24,.4);opacity:0;transition:opacity .25s}' +
      '.nj-mapsheet.on .nj-ms-dim{opacity:1}' +
      '.nj-ms-card{position:relative;width:100%;max-width:430px;background:#fff;border-radius:24px 24px 0 0;' +
        'padding:10px 22px calc(26px + env(safe-area-inset-bottom));box-shadow:0 -10px 30px rgba(20,20,40,.18);' +
        'transform:translateY(100%);transition:transform .32s cubic-bezier(.2,.9,.3,1.05);' +
        'font-family:"Noto Sans KR",-apple-system,BlinkMacSystemFont,system-ui,sans-serif;max-height:80vh;overflow-y:auto;box-sizing:border-box}' +
      '.nj-mapsheet.on .nj-ms-card{transform:translateY(0)}' +
      '.nj-ms-grab{width:36px;height:4px;border-radius:2px;background:#e2dfe8;margin:8px auto 14px}' +
      '.nj-ms-card h4{font-size:16px;font-weight:700;color:#282532;margin:0 0 14px}' +
      '.nj-ms-store{padding:14px 0;border-top:1px solid #f0eef4}' +
      '.nj-ms-store:first-of-type{border-top:none;padding-top:0}' +
      '.nj-ms-t{display:flex;align-items:center;gap:8px;font-weight:700;font-size:14.5px;color:#282532}' +
      '.nj-ms-t i{width:10px;height:10px;border-radius:50%;display:inline-block;flex:0 0 auto}' +
      '.nj-ms-badge{margin-left:2px;font-size:10px;font-weight:700;color:#F5679B;background:#fdedf3;border-radius:999px;padding:2px 8px}' +
      '.nj-ms-a{font-size:12.5px;color:#706b7d;margin-top:4px}' +
      '.nj-ms-links{display:flex;gap:16px;margin-top:8px}' +
      '.nj-ms-links a{font-size:12.5px;font-weight:700;color:#F5679B;text-decoration:none}' +
      '.nj-ms-close{width:100%;margin-top:16px;height:48px;border:none;border-radius:16px;background:#F5F4F8;color:#282532;font-weight:700;font-size:14px;cursor:pointer}';
    document.head.appendChild(st);
  }

})();
